"""Methods of estimation: MoM, MLE, M-estimators, Bayes."""
from nodespec import N

N("method_of_moments", "algorithm", "methods",
  "The method of moments estimates a d-dimensional theta by equating the first d population moments m_k(theta) = E_theta[X^k] to the sample moments mbar_k = (1/n) sum X_i^k and solving for theta.",
  parseable="solve  m_k(theta) = (1/n) sum_i X_i^k,  k = 1..d,  for theta_hat",
  symbols={"m_k(theta) = E_theta[X^k]": "the k-th population (raw) moment as a function of theta",
           "mbar_k = (1/n) sum X_i^k": "the k-th sample moment"},
  tcn="A system of d equations in d unknowns. Consistency follows from the LLN (mbar_k -> m_k) plus continuity of the inverse moment map; asymptotic normality from the CLT + delta method. Generally NOT efficient.",
  regime="asymptotic",
  hyps=[],
  proof=("LLN: sample moments -> population moments; continuous mapping through the (assumed invertible) moment map gives consistency; CLT + delta method give asymptotic normality",
         "prob_wlln", "cited",
         "the Chebyshev bound behind 'mbar_k -> m_k' is proof-checks.lean Stat.consistency_chebyshev"),
  spec=["N(mu, sigma^2): m_1 = mu, m_2 = sigma^2 + mu^2 => mu_hat = Xbar, sigma^2_hat = (1/n) sum (X_i - Xbar)^2 (the /n version)",
        "Gamma(a, b): match mean a/b and variance a/b^2 => a_hat, b_hat in closed form (the MLE needs iteration)",
        "uniform(0, theta): m_1 = theta/2 => theta_hat = 2 Xbar -- which can be LESS than max X_i, an impossible estimate"],
  cxd={"moments_exist": "Cauchy or t_2: no finite mean / variance, so mbar_1, mbar_2 do not converge and the method produces nonsense (prob_cauchy_no_mean). Estimate the median / IQR instead.",
       "moment_map_invertible": "if two parameter values give the same first d moments the system is not solvable for theta"},
  misuse=["using MoM when the MLE is tractable -- MoM throws away efficiency for no reason in the exponential-family case",
          "reporting a MoM estimate that lies outside the parameter space (negative variance, 2 Xbar < max)"],
  apps=["the generalized method of moments (GMM, Hansen 1982) is the workhorse of econometrics -- it estimates from moment conditions E[psi(X; theta)] = 0 without a full likelihood",
        "quick starting values for iterative MLE / EM"],
  related={"historically_precedes": ["maximum_likelihood_estimator"], "generalizes_to": ["m_estimator"]},
  sources=["casella_berger_2e", "hansen_gmm_1982"])

N("plug_in_principle", "definition", "methods",
  "The plug-in principle estimates a functional T(P) of the unknown law P by T(P_hat_n), where P_hat_n is the empirical distribution (mass 1/n at each observation).",
  parseable="theta_hat = T( P_hat_n )   for an estimand  theta = T(P)",
  symbols={"T(.)": "a statistical functional, type: map from laws to R^k (the mean, a quantile, the variance, a correlation)",
           "P_hat_n": "the empirical measure"},
  tcn="Requires the estimand to be expressed as a functional of P. Consistency comes from P_hat_n -> P (Glivenko-Cantelli) plus continuity of T; asymptotic normality from the functional delta method when T is Hadamard-differentiable.",
  regime="distribution_free",
  spec=["T(P) = E_P[X] => plug-in is Xbar; T(P) = Var_P(X) => plug-in is the /n sample variance",
        "T(P) = F^{-1}(1/2) => plug-in is the sample median",
        "T(P) = P(X in A) => plug-in is the sample proportion"],
  cxd={"T_continuous": "the density value f(x_0) is NOT a continuous functional of P in the sup metric -- there is no sqrt(n) plug-in estimator; density estimation is a genuinely nonparametric (slower-rate) problem (see kde_bias_variance_tradeoff)"},
  misuse=["plugging into a functional that is not smooth (a density, a mode, the number of modes) and expecting sqrt(n) behaviour",
          "forgetting the plug-in variance estimator (/n) is biased -- it is the MLE, not the UMVUE"],
  related={"required_by": ["plug_in_estimator"], "uses": ["empirical_cdf"]},
  sources=["wasserman_all_of_statistics", "van_der_vaart_asymptotic"])

N("maximum_likelihood_estimator", "definition", "methods",
  "The maximum likelihood estimator is theta_hat = argmax_{theta in Theta} L(theta) = argmax_{theta in Theta} ell(theta): the parameter value that makes the observed data most probable under the model.",
  parseable="theta_hat_MLE  in  argmax_{theta in Theta}  ell(theta)",
  symbols={"argmax": "the set of maximizers; theta_hat is any measurable selection when it is not unique",
           "ell(theta) = sum_i log f(X_i; theta)": "the log-likelihood"},
  tcn="Existence needs ell upper-semicontinuous and Theta compact (or ell -> -inf at the boundary) -- ra_compactness + ra_continuity. Uniqueness is separate (guaranteed if ell is strictly concave, e.g. a full-rank exponential family). The MLE is a function of any sufficient statistic.",
  hyps=[],
  proof=("existence: extreme value theorem on a compact Theta (or coercivity of ell); computation: solve the score equation (interior, smooth case) or search",
         "ra_compactness", "cited", None),
  spec=["Bernoulli: p_hat = Xbar; Poisson: lambda_hat = Xbar; N(mu, sigma^2): mu_hat = Xbar, sigma^2_hat = (1/n) sum (X_i - Xbar)^2 (divisor n -- biased)",
        "uniform(0, theta): theta_hat = max X_i -- the argmax is at the boundary, the score equation has no root",
        "logistic regression: no closed form; Newton-Raphson / IRLS on the concave log-likelihood"],
  cxd={"argmax_exists": "a two-component normal mixture with a free component variance: ell -> +inf as one component's variance -> 0 around a single data point -- the global MLE does not exist (only a consistent local maximizer does)",
       "argmax_unique": "a periodic likelihood (circular / phase parameter) can have multiple equal maxima"},
  misuse=["reporting a local maximum from an optimizer as 'the MLE' without checking for higher modes",
          "using MLE standard errors (inverse observed information) for uniform(0, theta) or other non-regular models",
          "forgetting the divisor-n bias of the normal-variance MLE"],
  apps=["the default fitting method in essentially every statistical model and in much of machine learning (cross-entropy loss IS the negative log-likelihood of a categorical model)",
        "phylogenetics, population genetics, econometrics (structural models), item-response theory -- all MLE-based"],
  related={"specializes_from": ["estimator"], "special_case_of": ["m_estimator"],
           "required_by": ["mle_score_equation", "mle_consistency", "likelihood_ratio_test"]},
  sources=["casella_berger_2e", "van_der_vaart_asymptotic"])

N("mle_score_equation", "proposition", "methods",
  "If the MLE theta_hat lies in the interior of Theta and ell is differentiable there, then it solves the score equation U(theta_hat) = 0.",
  parseable="theta_hat in int(Theta),  ell differentiable  =>  U(theta_hat) = grad ell(theta_hat) = 0",
  symbols={"U(theta_hat) = 0": "the first-order stationarity condition"},
  tcn="Fermat's stationarity condition, nothing more. It is NECESSARY, not sufficient -- a root of U can be a minimum or a saddle; and a boundary MLE need not be a root at all.",
  regime="exact",
  hyps=["true_parameter_interior"],
  proof=("first-order condition for an interior maximum of a differentiable function",
         "ra_mean_value_theorem", "core",
         "the 1-D statement (interior max => derivative zero) is proof-checks.lean Stat.interior_max_stationary via the MVT"),
  spec=["Bernoulli: U(p) = (sum x_i)/p - (n - sum x_i)/(1-p) = 0  =>  p_hat = xbar",
        "exponential family: U(eta) = sum T(x_i) - n grad A(eta) = 0  =>  grad A(eta_hat) = Tbar  (moment matching)",
        "uniform(0, theta): U(theta) = -n/theta, never 0 -- the MLE max x_i is NOT found this way"],
  cxd={"true_parameter_interior": "boundary MLE (uniform endpoint; a variance component estimated at 0; a probability estimated at exactly 0 or 1 in a small sample) -- U(theta_hat) != 0 and the score equation is the wrong tool",
       "differentiability": "non-smooth log-likelihood (Laplace location -> sample median): U is a step function, 0 is 'crossed' not 'hit'"},
  misuse=["solving U(theta) = 0 and stopping -- must verify it is a maximum (check the Hessian is negative definite) and that no boundary point does better",
          "iterating Newton from a bad start into a saddle point"],
  related={"required_by": ["mle_asymptotic_normality"], "uses": ["score_function"]},
  sources=["casella_berger_2e"])

N("mle_invariance", "proposition", "methods",
  "If theta_hat is an MLE of theta and g is any function, then g(theta_hat) is an MLE of g(theta) (using the induced / profile likelihood L*(eta) = sup_{g(theta) = eta} L(theta)).",
  parseable="theta_hat MLE of theta,  eta = g(theta)  =>  g(theta_hat) is an MLE of eta",
  symbols={"g": "an arbitrary function of the parameter (need not be one-to-one)",
           "L*(eta) = sup_{theta: g(theta) = eta} L(theta)": "the induced likelihood, whose maximizer is g(theta_hat)"},
  tcn="A closure property of the argmax under composition. For non-injective g one adopts the induced-likelihood definition and the property holds by construction.",
  regime="exact",
  hyps=[],
  proof=("the maximizer of the induced likelihood L*(eta) = sup_{g(theta)=eta} L(theta) is attained at eta = g(theta_hat)",
         "prob_continuous_mapping", "core",
         "argmax g(argmax L) = argmax L* is a set-identity; the 1-D monotone case is proof-checks.lean Stat.mle_invariance_monotone"),
  spec=["MLE of sigma is sqrt of the MLE of sigma^2 (which uses divisor n)",
        "MLE of the odds p/(1-p) is Xbar/(1-Xbar)",
        "MLE of P(X > c) in N(mu, sigma^2) is 1 - Phi((c - Xbar)/sigma_hat)"],
  cxd={"bias_is_not_preserved": "invariance is about the argmax, NOT about unbiasedness -- g(theta_hat) is typically biased even if theta_hat was unbiased (Jensen). E.g. sqrt(S^2) is a biased estimator of sigma."},
  misuse=["assuming the delta-method standard error transfers without the |g'| factor",
          "expecting g(UMVUE) to be the UMVUE of g(theta) -- invariance is an MLE property, not a UMVUE property"],
  related={"uses": ["maximum_likelihood_estimator"]},
  sources=["casella_berger_2e", "zehna_1966"])

N("mle_consistency", "theorem", "methods",
  "Under identifiability, a dominated model, and standard regularity (a compact Theta or a suitable uniform LLN / bracketing condition on the log-likelihood), the MLE is consistent: theta_hat_n -> theta_0 in P_{theta_0}-probability for every theta_0.",
  parseable="identifiable + regular  =>  theta_hat_n -->^p theta_0  under P_{theta_0},  for every theta_0",
  symbols={"theta_0": "the true parameter", "the Kullback-Leibler divergence K(theta_0, theta)": "which identifiability makes uniquely zero at theta = theta_0"},
  tcn="An asymptotic guarantee. Wald's argument: (1/n) ell(theta) -> -K(theta_0, theta) + const uniformly; the limit is uniquely maximized at theta_0 (identifiability); so its argmax theta_hat_n -> theta_0. The 'uniformly' step needs a compactness / bracketing condition and is where proofs differ.",
  regime="asymptotic",
  hyps=["identifiability"],
  proof=("Wald (1949): uniform LLN for the normalized log-likelihood + unique maximizer of the KL-divergence limit at theta_0",
         "prob_slln", "cited",
         "CITED -- Wald 1949; van der Vaart Asymptotic Statistics Thm 5.7. The identifiability => unique KL minimizer step is elementary; the uniform LLN is the analytic content."),
  spec=["all exponential families on the interior: consistent",
        "N, Gamma, Poisson, logistic regression (with non-degenerate design): consistent",
        "well-separated mixture models: the consistent ROOT of the likelihood equation exists even when the global MLE does not"],
  cxd={"identifiability": "N(alpha + beta, 1): (alpha_hat, beta_hat) is NOT consistent -- it wanders along the ridge alpha + beta = Xbar. Only the identified function alpha + beta is consistently estimated.",
       "regularity_uniform_LLN": "Neyman-Scott problem: N(mu_i, sigma^2) with one mu_i per observation and n -> inf. The number of parameters grows with n; the MLE of sigma^2 converges to sigma^2/2, NOT sigma^2 -- inconsistent. Fixed finite d is essential."},
  misuse=["assuming consistency for a model with a growing parameter dimension (Neyman-Scott, high-dimensional regression with p ~ n)",
          "citing consistency as evidence the estimate at your actual n is close to the truth"],
  related={"required_by": ["mle_asymptotic_normality"], "strengthened_by": ["mle_asymptotic_normality"]},
  sources=["wald_1949", "van_der_vaart_asymptotic", "neyman_scott_1948"])

N("mle_asymptotic_normality", "theorem", "methods",
  "Under identifiability, theta_0 interior, log f in C^3 with a dominated third derivative, and I(theta_0) positive definite, the MLE satisfies sqrt(n)(theta_hat_n - theta_0) -> N(0, I(theta_0)^{-1}) in distribution; the MLE is asymptotically efficient.",
  parseable="regular model  =>  sqrt(n)( theta_hat_n - theta_0 )  -->^d  N( 0, I(theta_0)^{-1} )",
  symbols={"I(theta_0)^{-1}": "the inverse per-observation Fisher information -- the Cramer-Rao asymptotic variance",
           "the sample version": "n(theta_hat - theta_0) approx N(0, (n I)^{-1}); SE_j = sqrt((n I(theta_hat))^{-1}_jj)"},
  tcn="An asymptotic distributional result. Proof: Taylor-expand 0 = U(theta_hat) about theta_0: 0 = U(theta_0) + U'(theta_bar)(theta_hat - theta_0). Then sqrt(n)(theta_hat - theta_0) = [-(1/n) U'(theta_bar)]^{-1} [(1/n^{1/2}) U(theta_0)]. Numerator -> N(0, I(theta_0)) by the CLT (score identity + information equality give mean 0, variance I). Denominator -> I(theta_0) by the LLN. Slutsky assembles N(0, I^{-1} I I^{-1}) = N(0, I^{-1}).",
  regime="asymptotic",
  hyps=["true_parameter_interior", "fisher_information_positive_definite", "log_likelihood_smooth", "identifiability"],
  proof=("Taylor-expand the score equation about theta_0; CLT for the score, LLN for the observed information, Slutsky",
         "prob_clt", "cited",
         "CITED -- Cramer 1946; van der Vaart Thm 5.39. The Slutsky assembly N(0, A^{-1} B A^{-1}) with A = B = I is proof-checks.lean Stat.sandwich_reduces_when_info_equality; the deep CLT-for-the-score step is cited."),
  spec=["Bernoulli: sqrt(n)(p_hat - p) -> N(0, p(1-p)) -- the de Moivre-Laplace / normal approximation to the binomial proportion",
        "N(mu, sigma^2): sqrt(n)((mu_hat, sigma^2_hat) - (mu, sigma^2)) -> N(0, diag(sigma^2, 2 sigma^4)) -- mu_hat and sigma^2_hat asymptotically independent",
        "logistic regression: sqrt(n)(beta_hat - beta) -> N(0, (E[p(1-p) x x^T])^{-1}) -- the basis of the reported z-values"],
  cxd={"log_likelihood_smooth": "Laplace location: the MLE (sample median) IS sqrt(n)-normal but with variance 1 (= 1/(4 f(0)^2)), reached by a non-Taylor argument -- the C^3 route fails though the conclusion's SHAPE survives",
       "support_independent_of_theta": "uniform(0, theta): n(theta - theta_hat) -> Exponential -- rate n, non-normal limit; the theorem's conclusion is simply false",
       "true_parameter_interior": "one-sided boundary (variance component = 0): the limit is a half-normal, not a normal",
       "fisher_information_positive_definite": "non-identified direction: I singular, I^{-1} undefined, no sqrt(n)-normal limit along the flat direction"},
  misuse=["using I(theta_0)^{-1}/n as an EXACT finite-sample variance -- it is a limit; at small n the sampling distribution of a nonlinear MLE is skewed",
          "trusting Wald intervals theta_hat +- z SE for a near-boundary parameter (a proportion near 0/1) -- the score or LR interval is far better there",
          "applying it to non-regular models"],
  apps=["the source of every 'estimate +- standard error' and z-/p-value in the output of a fitted GLM, survival model, or structural equation model",
        "the delta method (this + a smooth transform) delivers the SE of any function of the fitted parameters -- odds ratios, predicted probabilities, EC50s"],
  related={"strengthens": ["mle_consistency"], "required_by": ["wald_test", "wilks_theorem", "large_sample_wald_interval", "bernstein_von_mises"],
           "uses": ["information_equality"]},
  sources=["cramer_1946", "van_der_vaart_asymptotic", "lehmann_casella_tpe"])

N("m_estimator", "definition", "methods",
  "An M-estimator maximizes an empirical criterion theta_hat = argmax_theta (1/n) sum_i m(X_i; theta), or equivalently solves the estimating equation (1/n) sum_i psi(X_i; theta) = 0 with psi = grad_theta m; the MLE is the case m = log f.",
  parseable="theta_hat  solves  (1/n) sum_i psi(X_i; theta) = 0",
  symbols={"m(x; theta)": "the per-observation criterion (log-density, negative loss, ...)",
           "psi(x; theta) = grad_theta m": "the estimating function / influence-defining function"},
  tcn="Generalizes the MLE by decoupling the criterion from the true density. Under E_theta[psi(X; theta)] = 0 (the estimating equation is 'unbiased') the estimator is consistent for that theta; asymptotic normality with the SANDWICH covariance A^{-1} B A^{-T}, A = -E[grad psi], B = E[psi psi^T].",
  regime="asymptotic",
  hyps=[],
  proof=("Z-estimator master theorem: consistency from a uniform LLN for the criterion, asymptotic normality from linearizing the estimating equation + CLT for (1/sqrt n) sum psi(X_i; theta_0)",
         "mle_asymptotic_normality", "cited", None),
  spec=["Huber's robust location estimator: psi(x) = clip(x - theta, -c, c) -- bounded influence, resists outliers",
        "quantile regression: m(x; theta) = rho_tau(y - x^T theta), the check function -- estimates conditional quantiles",
        "quasi-likelihood / GEE: psi from a mean model only, no full distribution"],
  cxd={"estimating_equation_unbiased": "if E_theta[psi(X; theta)] != 0 (a misspecified mean model, or Huber's psi under an asymmetric error) the M-estimator converges to the wrong value theta* -- the solution of E[psi(X; theta*)] = 0, not theta"},
  misuse=["reporting inverse-Hessian (naive) standard errors for an M-estimator that is not the MLE -- the sandwich B != A there and the naive SE is wrong",
          "assuming robustness of the estimator implies robustness of its standard error"],
  related={"generalizes_from": ["maximum_likelihood_estimator", "method_of_moments"], "required_by": ["sandwich_variance"]},
  sources=["huber_robust_statistics", "van_der_vaart_asymptotic", "stefanski_boos_2002"])

N("sandwich_variance", "proposition", "methods",
  "An M-estimator solving (1/n) sum psi(X_i; theta) = 0 has asymptotic covariance A(theta)^{-1} B(theta) A(theta)^{-T} with A = -E_theta[grad_theta psi(X; theta)] and B = E_theta[psi(X; theta) psi(X; theta)^T]; it reduces to I(theta)^{-1} when psi is the true score (information equality: A = B = I).",
  parseable="AVar(theta_hat) = A^{-1} B A^{-T},   A = -E[grad psi],  B = E[psi psi^T]",
  symbols={"the 'bread' A^{-1}": "from the derivative of the estimating equation",
           "the 'meat' B": "the variance of the estimating function",
           "the estimated version": "A_hat = -(1/n) sum grad psi(X_i; theta_hat), B_hat = (1/n) sum psi psi^T at theta_hat -- the Huber-White / robust standard error"},
  tcn="A covariance formula, asymptotic. The reduction A^{-1} B A^{-1} -> I^{-1} needs the information equality (correct model). Under misspecification A != B and the sandwich is the only correct large-sample variance.",
  regime="asymptotic",
  hyps=[],
  proof=("linearize the estimating equation: sqrt(n)(theta_hat - theta) = A^{-1} (1/sqrt n) sum psi(X_i; theta) + o_p(1); apply the CLT to the sum (covariance B)",
         "m_estimator", "core",
         "the reduction A = B = I(theta) under the information equality is proof-checks.lean Stat.sandwich_reduces_when_info_equality"),
  spec=["OLS with heteroskedastic errors: the HC0-HC3 'robust' / 'Huber-White' standard errors are the sandwich with psi = x(y - x^T beta)",
        "GEE (longitudinal data): the sandwich gives valid SEs even if the working correlation is wrong",
        "a correctly specified GLM: sandwich SE approx model-based SE (they diverge => evidence of misspecification -- an informal specification test)"],
  cxd={"finite_meat_and_bread": "if B = E[psi psi^T] is infinite (heavy-tailed influence) the sandwich variance is infinite and no sqrt(n) normal limit holds"},
  misuse=["using robust SEs to 'fix' a model whose POINT estimates are inconsistent -- the sandwich only fixes the variance, not the bias from a wrong mean model",
          "applying sandwich SEs at small n, where they are downward biased (hence the HC2/HC3 finite-sample corrections)"],
  related={"uses": ["m_estimator", "information_equality"]},
  sources=["huber_robust_statistics", "white_1982", "stefanski_boos_2002"])

N("bayes_estimator", "definition", "methods",
  "Given a prior pi on Theta and a loss L(theta, a), the Bayes estimator is the decision rule delta_pi(x) = argmin_a E[ L(theta, a) | X = x ] = argmin_a int L(theta, a) pi(theta | x) dtheta: it minimizes the posterior expected loss for each observed x.",
  parseable="delta_pi(x)  in  argmin_a  E_{theta | x}[ L(theta, a) ]",
  symbols={"pi(theta)": "the prior density on Theta (a modeling input)",
           "pi(theta | x) proportional to L(x; theta) pi(theta)": "the posterior",
           "delta_pi": "the Bayes rule / Bayes estimator"},
  tcn="An argmin over actions of the posterior risk. Well-posed whenever the posterior exists (proper, or improper with a finite normalizer) and the posterior loss is finite. It is automatically a function of a sufficient statistic.",
  regime="bayesian",
  hyps=[],
  proof=("minimize the Bayes risk r(pi, delta) = E_X E_{theta|X}[L] by minimizing the inner (posterior) expectation for each x -- see bayes_rule_minimizes_bayes_risk",
         "bayes_rule_minimizes_bayes_risk", "core", None),
  spec=["squared-error loss: delta_pi(x) = posterior mean E[theta | x] (posterior_mean_rule)",
        "absolute-error loss: delta_pi(x) = a posterior median (posterior_median_rule)",
        "0-1 loss on a discrete Theta: delta_pi(x) = the posterior mode (MAP estimate)"],
  cxd={"proper_posterior": "an improper prior can yield an improper posterior (e.g. pi(sigma) = 1/sigma with n = 0, or the Bayes/Neyman-Scott hierarchical models) -- then no Bayes estimator exists and reported 'posterior summaries' are meaningless",
       "finite_posterior_loss": "squared-error loss with a Cauchy posterior: E[theta | x] does not exist; use the posterior median"},
  misuse=["reporting a Bayes estimate without stating the prior -- the prior is part of the answer",
          "using a 'flat' prior on an unbounded parameter and assuming it is uninformative -- it is often improper and can be strongly informative after a nonlinear reparametrization"],
  apps=["Bayesian hierarchical shrinkage (small-area estimation, sports analytics, the 'James-Stein as empirical Bayes' story) -- the posterior mean pools information across units",
        "Kalman filtering is exact Bayesian estimation for the linear-Gaussian state-space model",
        "Thompson sampling for bandits draws from the posterior and acts greedily"],
  related={"specializes_from": ["estimator", "decision_rule"], "required_by": ["posterior_mean_rule", "posterior_median_rule", "conjugate_prior", "bernstein_von_mises"]},
  sources=["berger_statistical_decision_theory", "robert_bayesian_choice"])

N("posterior_mean_rule", "theorem", "methods",
  "Under squared-error loss L(theta, a) = (theta - a)^2, the Bayes estimator is the posterior mean: delta_pi(x) = E[theta | X = x].",
  parseable="L(theta, a) = (theta - a)^2   =>   delta_pi(x) = E[theta | x]",
  symbols={"E[theta | x]": "the mean of the posterior distribution"},
  tcn="An argmin computed by completing the square: E[(theta - a)^2 | x] = Var(theta | x) + (E[theta | x] - a)^2, minimized at a = E[theta | x]. Same algebra as the bias-variance decomposition and the L^2-projection property of conditional expectation.",
  regime="bayesian",
  hyps=[],
  proof=("E[(theta - a)^2 | x] = Var(theta | x) + (E[theta|x] - a)^2; the first term is free of a, the second is minimized (to 0) at a = E[theta | x]",
         "prob_conditional_expectation", "core",
         "validation/proof-checks.lean Stat.posterior_mean_completes_square -- E[(t - a)^2] = E[(t - Et)^2] + (Et - a)^2, minimized at a = E t; identical to Stat.mse_decomp"),
  spec=["Beta-Bernoulli: prior Beta(alpha, beta), data sum x_i = s in n trials => posterior Beta(alpha + s, beta + n - s), posterior mean (alpha + s)/(alpha + beta + n) -- a shrunk version of s/n toward the prior mean",
        "Normal-Normal: prior N(mu_0, tau^2), data Xbar with known sigma^2/n => posterior mean is a precision-weighted average of mu_0 and Xbar",
        "as n -> inf the posterior mean -> the MLE (Bernstein-von Mises)"],
  cxd={"posterior_mean_exists": "heavy-tailed posterior (Cauchy prior + one observation): E[theta | x] is undefined; the posterior-median rule (absolute loss) still works",
       "squared_loss_appropriate": "if over- and under-estimation have different costs (inventory, dosing) the posterior mean is the wrong summary -- use the rule for the actual asymmetric loss"},
  misuse=["reporting the posterior mean for a skewed posterior when the posterior median or mode better represents 'the estimate'",
          "forgetting that the posterior mean is a shrinkage estimator -- it is deliberately biased toward the prior"],
  related={"special_case_of": ["bayes_estimator"], "uses": ["prob_conditional_expectation"],
           "commonly_confused_with": ["p_value"]},
  sources=["berger_statistical_decision_theory", "casella_berger_2e"])

N("posterior_median_rule", "theorem", "methods",
  "Under absolute-error loss L(theta, a) = |theta - a|, the Bayes estimator is a posterior median: any m with P(theta <= m | x) >= 1/2 and P(theta >= m | x) >= 1/2.",
  parseable="L(theta, a) = |theta - a|   =>   delta_pi(x) = median( theta | x )",
  symbols={"m": "a posterior median (an interval of minimizers if the posterior has a flat spot at 1/2)"},
  tcn="An argmin: d/da E[|theta - a| | x] = P(theta < a | x) - P(theta > a | x), which changes sign at the median. The median minimizes expected absolute deviation -- the L^1 analogue of the mean minimizing expected squared deviation.",
  regime="bayesian",
  hyps=[],
  proof=("E[|theta - a|] has left-derivative P(theta <= a) - P(theta > a); it is <= 0 for a below the median and >= 0 above => minimized at the median",
         "posterior_mean_rule", "core",
         "the sign-change-at-the-median argument; instance check in instance-checks.bc"),
  spec=["a symmetric unimodal posterior: median = mean = mode, all three rules agree",
        "a right-skewed posterior (variance, rate parameters): posterior median < posterior mean -- the median is the more stable point summary",
        "check loss (quantile) generalization: L_tau(theta, a) = (tau - 1{theta < a})(theta - a) gives the tau-th posterior quantile"],
  cxd={"none_all_hypotheses_essential": "the rule needs only that the posterior has a median (always true) and finite E|theta| for the risk to be finite -- weaker than the posterior-mean rule's requirement"},
  misuse=["reporting a posterior median but a 'mean +- SD' credible interval -- mixing loss functions"],
  related={"special_case_of": ["bayes_estimator"]},
  sources=["berger_statistical_decision_theory"])

N("conjugate_prior", "definition", "methods",
  "A family of priors F is conjugate to a likelihood model if for every prior in F and every dataset the posterior is again in F; the update is then a closed-form change of the family's hyperparameters.",
  parseable="pi in F  =>  pi(. | x) in F   for every x",
  symbols={"F": "the conjugate family (Beta, Gamma, Normal-inverse-Gamma, Dirichlet, ...)",
           "hyperparameters": "the parameters of the prior, updated by simple sufficient-statistic arithmetic"},
  tcn="A closure property of a prior family under Bayesian updating for a given likelihood. Every exponential family has a conjugate prior (the exp-family prior on the natural parameter with T-plus-count hyperparameters).",
  regime="bayesian",
  spec=["Beta is conjugate to Bernoulli/binomial: Beta(a, b) + s successes in n => Beta(a + s, b + n - s)",
        "Gamma is conjugate to Poisson: Gamma(a, b) + counts summing to S in n obs => Gamma(a + S, b + n)",
        "Normal-inverse-Gamma is conjugate to the normal with unknown mean and variance",
        "Dirichlet is conjugate to the multinomial"],
  cxd={"exists_and_is_flexible_enough": "conjugate priors can be too rigid -- e.g. the Beta cannot be bimodal, the Gamma cannot have a heavy left tail; a genuinely different prior belief forces non-conjugate computation (MCMC)"},
  misuse=["choosing a conjugate prior for computational convenience and then interpreting it as 'objective'",
          "reading the pseudo-count hyperparameters as data when reporting the effective sample size"],
  apps=["Latent Dirichlet Allocation (topic models): Dirichlet-multinomial conjugacy is what makes the collapsed Gibbs sampler tractable",
        "Thompson sampling for Bernoulli bandits uses the Beta-Bernoulli conjugate update per arm",
        "Bayesian A/B testing dashboards update Beta posteriors in closed form in real time"],
  related={"uses": ["prob_beta", "prob_binomial", "bayes_estimator"], "illustrated_by": ["exponential_family"]},
  sources=["gelman_bda3", "robert_bayesian_choice"])

N("bernstein_von_mises", "theorem", "methods",
  "Under the same regularity as MLE asymptotic normality and any prior with positive continuous density near theta_0, the posterior distribution of sqrt(n)(theta - theta_hat_n) converges (in total variation, in P_{theta_0}-probability) to N(0, I(theta_0)^{-1}); consequently Bayesian credible sets have frequentist coverage 1 - alpha asymptotically.",
  parseable="regular model + smooth positive prior  =>  || pi( sqrt(n)(theta - theta_hat_n) in . | X ) - N(0, I(theta_0)^{-1}) ||_TV  -->^p  0",
  symbols={"pi(. | X)": "the posterior", "TV": "total variation distance",
           "consequence": "a 95% credible interval is asymptotically a 95% confidence interval"},
  tcn="A convergence-of-measures statement about the posterior, holding in P_{theta_0}-probability (a frequentist statement about a Bayesian object). The prior washes out at rate 1/sqrt(n).",
  regime="bayesian",
  hyps=["true_parameter_interior", "fisher_information_positive_definite", "log_likelihood_smooth", "identifiability"],
  proof=("Taylor-expand the log-posterior about theta_hat_n; the quadratic term dominates, the prior contributes O(1/n), the remainder is o_p(1) uniformly on sqrt(n)-neighbourhoods",
         "mle_asymptotic_normality", "cited",
         "CITED -- van der Vaart Asymptotic Statistics Ch. 10; Le Cam. Not formalized."),
  spec=["Beta(a,b)-Bernoulli: the Beta(a + s, b + n - s) posterior is asymptotically N(p_hat, p_hat(1-p_hat)/n) -- matches the Wald interval",
        "the prior choice affects only the O(1/n) correction for large n",
        "the practical upshot: for regular parametric models, large-sample Bayesian and frequentist intervals agree"],
  cxd={"true_parameter_interior": "boundary parameter (a variance component at 0): the posterior piles up against the boundary and is NOT asymptotically normal; credible intervals do NOT have frequentist coverage",
       "fixed_finite_dimension": "in nonparametric / high-dimensional models Bernstein-von Mises can FAIL -- credible bands can badly under- or over-cover (Cox 1993, Freedman 1999); this is an active research area",
       "identifiability": "non-identified parameter: the posterior does not concentrate and coverage is prior-driven"},
  misuse=["citing it to claim Bayesian and frequentist intervals 'always' agree -- it is parametric, regular, large-n only",
          "assuming a credible interval has frequentist coverage in a hierarchical or nonparametric model"],
  related={"approximates": ["mle_asymptotic_normality"], "required_by": [], "uses": ["credible_interval"]},
  sources=["van_der_vaart_asymptotic", "le_cam_asymptotic_methods", "freedman_1999"])
